"""Convert a 'glob' pattern for file name matching to a regular
    expression. E.g. "foo.? bar*" -> "foo\.. \bar.*" """
def glob_to_regex(pattern: Any) -> object {
    return (
        "^" + pattern.replace(".", "\.").replace("*", ".*").replace("?", ".") + "$"
    );
}

